exec(open('tools/common.py').read())
# Intermediate unit 33 – Describing public events. Bám sách: trang 70–71 (đã xem ảnh trang) + đáp án + Mini dictionary. Không chép nguyên văn.
# call off, put off (u1), put back = dời sự kiện (u11) đã có thẻ. take off/put on có nghĩa mới → sense. pour out, put forward (sự kiện) chỉ có trong Mini, không có trên trang → bỏ qua.
theory = (
 H("A", "A review of an event", "Bài điểm một sự kiện")
 + P("A review of a comedy show at the London Arts Centre: the show <b>was booked up</b> for weeks (no tickets left); on the first night the public <b>poured in</b> (arrived in huge numbers) and the hall was <b>packed out</b> (very full). The comedians <b>take off</b> politicians (copy them to make people laugh) and could easily <b>stand in</b> for the country’s real leaders (take their place for a short time). The show was <b>put on</b> (organised) as a protest after an election, timed to <b>tie in with</b> National Democracy Week (happen at the same time). But it was third-rate: many people <b>walked out</b> (left before the end). The performers <b>sent up</b> the Prime Minister amusingly (made him look stupid by copying him). Despite a large <b>turnout</b> (number of people who came), the reviewer doubts it will last.",
     "Bài điểm một chương trình hài ở Trung tâm Nghệ thuật London: chương trình <b>was booked up</b> mấy tuần liền (hết vé); đêm đầu khán giả <b>poured in</b> (ùn ùn kéo đến) và hội trường <b>packed out</b> (chật kín). Các danh hài <b>take off</b> chính trị gia (nhại để gây cười) và có thể dễ dàng <b>stand in</b> thay các lãnh đạo thật (đóng thế một thời gian). Chương trình được <b>put on</b> (tổ chức) để phản đối kết quả bầu cử, canh giờ <b>tie in with</b> Tuần lễ Dân chủ quốc gia (trùng thời điểm). Nhưng chất lượng tồi: nhiều người <b>walked out</b> (bỏ về giữa chừng). Các nghệ sĩ <b>sent up</b> thủ tướng khá buồn cười (nhại cho lố bịch). Dù <b>turnout</b> đông (số người đến), người viết nghi chương trình khó trụ lâu.")
 + H("B", "Other verbs connected with events", "Các động từ khác liên quan đến sự kiện")
 + T([
   ("call off sth", "cancel something no longer possible or useful – a sports event with only 20 tickets sold (card in Unit 1)", "hủy – sự kiện thể thao chỉ bán được 20 vé (đã có thẻ ở bài 1)"),
   ("cram into/in", "go into a place that is too small so it becomes very full – 300 people in a hall for 200", "chen chúc vào – 300 người trong hội trường 200 chỗ"),
   ("pass off", "happen, especially in a good way – a peaceful demonstration", "diễn ra (suôn sẻ) – cuộc biểu tình ôn hòa"),
   ("put off sth", "postpone – a match in heavy rain (card in Unit 1)", "hoãn – trận đấu vì mưa to (đã có thẻ ở bài 1)"),
   ("put back sth", "arrange something for a later time – a staff meeting (card in Unit 11)", "dời lại – cuộc họp nhân viên (đã có thẻ ở bài 11)"),
 ])
 + NOTE("<b>Tip</b>: learn a group of phrasal verbs together by linking them in a story, as in the review in A, and make up stories for verbs in your notebook. <b>Exercise 33.2</b> also uses <i>turn out</i> (come to an event): many people <i>turned out</i> for the meeting.",
        "<b>Mẹo</b>: học một nhóm phrasal verb bằng cách nối chúng thành câu chuyện như bài điểm ở mục A, và tự đặt chuyện cho các động từ trong sổ. <b>Bài 33.2</b> còn dùng <i>turn out</i> (đến dự): nhiều người <i>turned out</i> dự cuộc họp.")
)
